begin; select set_config('request.jwt.claim.role','service_role',true); do $$ declare p record; payload jsonb; result jsonb; id uuid:=gen_random_uuid(); before_stock numeric; after_stock numeric; begin select q.id,q.site_id,q.stock,q.price into p from public.products q join public.sites s on s.id=q.site_id where q.stock between 6 and 1000 and q.price between 1 and 1000 and lower(q.approval_status)='approved' and lower(s.status) in ('active','open') limit 1; if p.id is null then raise exception 'No test product'; end if; before_stock:=p.stock; payload:=jsonb_build_object('id',id,'site_id',p.site_id,'payment_method','Cash','amount_tendered',1000000,'receipt_number','ROLLBACK-'||id,'mobile_payment_channel','TEST','mobile_transaction_ref',id::text,'customer_phone','TEST-ONLY'); result:=public.create_pos_sale_atomic(payload,jsonb_build_array(jsonb_build_object('product_id',p.id,'quantity',1))); if result->>'mobile_transaction_ref'<>id::text then raise exception 'Payment reference not persisted'; end if; select stock into after_stock from products where products.id=p.id; if after_stock<>before_stock-1 then raise exception 'Stock not decremented'; end if; result:=public.create_pos_sale_atomic(payload,jsonb_build_array(jsonb_build_object('product_id',p.id,'quantity',1))); if (select stock from products where products.id=p.id)<>after_stock then raise exception 'Duplicate decrement'; end if;
begin
 perform public.create_pos_sale_atomic((payload - 'mobile_transaction_ref') || jsonb_build_object('id',gen_random_uuid(),'receipt_number','ROLLBACK-OVER-'||id,'amount_tendered',10000000),jsonb_build_array(jsonb_build_object('product_id',p.id,'quantity',p.stock+100)));
 raise exception 'Oversell was accepted' using errcode='XX000';
exception when raise_exception then null; end;
if (select stock from products where products.id=p.id)<>after_stock then raise exception 'Rejected sale altered stock'; end if;
end $$; rollback; select 'Atomic sale and retry passed; rollback complete' as result;
